LORE.push(
  {ch:447, n:'A Familiar Name in an Old Ledger', t:'In the Stanson estate\'s records the party found the name Lysenne used as an alias, Madame Linse, a woman who deliberately lived under a different identity and ran a network across the southern ports after the kingdom fell, helping nobles, scholars and others relocate.'},
  {ch:448, n:'The Woman Called Orchid', t:'The trail led to a woman living in the western quarter as Orchid. She remembered the fall of Lysenne: warnings, betrayals from within, and a small royal child she was trusted to carry to safety before losing her. A woman from outside the kingdom took the child, and Orchid recalled a flower symbol.'},
  {ch:449, n:'Zhaohua', t:'Orchid was confirmed as Princess Zhaohua, Sally\'s older half-sister, who had believed Zhaoning died in the fall of Lysenne. She had buried who she was to survive. Sally did not remember her, but felt it as a missing part of herself.'},
  {ch:450, n:'My Little Sister Survived', t:'For Zhaohua it was simply the truth she never dared to hope for: her little sister survived. Sally did not remember being a princess or a sister, but remembered Lily, then Sally Sin, later Sally Sun. Zhaohua told her she did not need to remember now.'},
  {ch:451, n:'I Don\'t Remember You', t:'Sally told Zhaohua she did not remember being a princess or a little sister, only Lily, Sally Sin and Sally Sun. Zhaohua said it hurt but she would not force her to remember; she would get to know the sister Sally was now.'},
  {ch:452, n:'Then Let Me Meet Sally', t:'Zhaohua accepted she could not restore the past by force and chose to meet Sally as she is now. Sally told her of Lily, Sally Sin and Sally Sun, the same person under different names. They agreed to get to know each other at Sally\'s pace, two women choosing slowly to become sisters again.'}
);

/* ---- Arc XVIII, chapters 453-461: the sisters, the Stanson house, Lenny's wedding (461 closes the arc) ---- */
LOCATIONS.capital.spots.push(
  {id:'hz453a', kind:'investigate', n:'You Always Loved Music', icon:'🎼', ch:453, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'A formal melody changed.',
   clues:['Zhaohua: "You always loved music. You would take a formal melody and change it... adding your own little twists until it sounded like a new song. You used to sit here for hours, just playing and experimenting. Everyone said you had a stubborn but beautiful ear for music."', 'Sally: "I... I do enjoy music. But I don\'t remember doing that when I was little."'], rw:{xp:445100, gold:91320}},
  {id:'hz453b', kind:'investigate', n:'Sweet Cakes and Osmanthus', icon:'🍵', ch:453, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'She never liked bitter food.',
   clues:['Zhaohua: "You never liked bitter food. You would always push the herbs aside. And you loved sweet tea with dried osmanthus. You would sneak these sweet cakes whenever you could."', 'Sally: "This... I think I like it. I don\'t remember this specifically, but it does taste good."'], rw:{xp:445400, gold:91380}, needFlag:'inv_hz453a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz453c', kind:'investigate', n:'Flowers Behind Your Ear', icon:'💜', ch:453, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Lavender, without realising.',
   clues:['Zhaohua: "And lavender. You were always drawn to this color. Even now... you still reach for lavender without realising it. You used to tuck flowers behind your ear like this. You said it made you feel like you could breathe."', 'Sally: "I don\'t remember that either... But... I do like wearing flowers. It feels... familiar. I don\'t know why... But it feels good."'], rw:{xp:445700, gold:91440}, needFlag:'inv_hz453b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz453d', kind:'investigate', n:'I Can See Her in You', icon:'🌙', ch:453, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Just her sister, now.',
   clues:['Zhaohua: "You always asked so many questions. You were stubborn, but curious. You would argue about rules, but also work so hard on the things you cared about. You are still like that. Even if you do not remember the child, I can see her in you."', 'Sally: "Then maybe... I do not have to remember everything to be your sister. I can just be your sister... now. Thank you... for telling me these stories."'], rw:{xp:446000, gold:91500}, needFlag:'inv_hz453c', lockMsg:'🔒 Finish the previous clue first'},
);
LOCATIONS.stanson_estate.spots.push(
  {id:'hz454a', kind:'investigate', n:'The Household Accounts', icon:'📒', ch:454, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Leon\'s work.',
   clues:['During the years Levi was absent, Leon quietly shouldered more and more responsibilities at the estate. Leon: "These are the household accounts for the past year. The estate\'s finances are stable, and the key staff remain loyal."', 'His father: "You have done well, Leon. This is more than I expected."'], rw:{xp:446300, gold:91560}},
  {id:'hz454b', kind:'investigate', n:'I Am Not Like Him', icon:'🏯', ch:454, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'He prefers this life.',
   clues:['Leon: "Brother was always destined for greater things. I am not like him. I do not seek war or glory. I prefer this life: managing the estate, protecting our people, and making sure nothing falls apart again."', 'Levi\'s path has always led elsewhere. He chases truths and dangers, often at great cost.'], rw:{xp:446600, gold:91620}, needFlag:'inv_hz454a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz454c', kind:'investigate', n:'Someone Must Look After Our Home', icon:'🕯️', ch:454, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'A role he can carry.',
   clues:['Leon: "I will stay at the estate. Someone must look after our home. It is a role I can accept, and one I am willing to carry."', 'His father: "The Stanson name needs someone who can remain. You have proven yourself, Leon. The estate is safer with you here. I am not asking you to become your brother. I am asking you to be yourself."'], rw:{xp:446900, gold:91680}, needFlag:'inv_hz454b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz454d', kind:'investigate', n:'But for Now, I Am Here', icon:'🍵', ch:454, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Sally sees him.',
   clues:['Leon is not Levi. But his presence gives the estate stability, and its people someone to rely on. Sally sees a different side of Leon, not the shadow of Levi, but a man who has quietly grown through responsibility.', 'Sally: "You have already done a great deal. It is not easy to stay and carry so much." Leon: "There is still much to do... But for now, I am here."'], rw:{xp:447200, gold:91740}, needFlag:'inv_hz454c', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz455a', kind:'investigate', n:'I Intend to Marry', icon:'📢', ch:455, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Lenny\'s announcement.',
   clues:['Lenny reveals that he intends to marry, and that the girl he is courting is already expecting a baby. The family\'s anxiety over succession collapses almost immediately. Lenny: "Father. I would like to make an announcement. I intend to marry. And the girl I am courting is already expecting a baby."', 'His father: "...You\'re already expecting a child? Lenny..."'], rw:{xp:447500, gold:91800}},
  {id:'hz455b', kind:'investigate', n:'I Will Take Responsibility', icon:'🌸', ch:455, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'A gentle fiancée.',
   clues:['Lenny: "Yes. We wanted to tell the family as soon as everything was confirmed. I will take responsibility for both of them."', 'Lenny\'s fiancée is gentle and kind, though visibly nervous in front of the Stanson elders: "Please... I will do my best to be a good wife, and a good mother to our child."'], rw:{xp:447800, gold:91860}, needFlag:'inv_hz455a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz455c', kind:'investigate', n:'No Need to Rush Levi', icon:'📜', ch:455, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'The future is secured.',
   clues:['His father: "Then there is no need to rush Levi into marriage any longer. The Stanson future is secured. Our focus can return to what truly matters, the estate, its people, and stability."', 'Lenny: "...So this... settles it. Thank you for trusting me. I will make sure both you and our child are safe here."'], rw:{xp:448100, gold:91920}, needFlag:'inv_hz455b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz455d', kind:'investigate', n:'Less Heavy', icon:'🌙', ch:455, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Sally\'s relief.',
   clues:['Sally watches Lenny quietly, feeling genuine relief for him. For the first time in a long while, the Stanson estate feels less heavy. Sally: "You\'ve done well, Lenny. It takes courage to make such a decision. I\'m glad you have someone you trust."', 'Lenny: "Thank you, Sally. Your support means a lot. I hope you\'ll look after her too, when I\'m not around." The pressure to force Levi into marriage has ended. A new chapter begins.'], rw:{xp:448400, gold:91980}, needFlag:'inv_hz455c', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz456a', kind:'investigate', n:'I Will Take Responsibility', icon:'🏯', ch:456, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Leon\'s pledge.',
   clues:['At House Stanson, the family finally accepts a new path. Leon: "I, Leon Stanson, will take responsibility for the estate and the family line. The household, its people, and its future will be my duty."', 'The father: "You have grown into a dependable man, Lenny. This is what the estate needs." The mother: "You are well suited for this role. The family can finally be at ease. It is the right path for House Stanson."'], rw:{xp:448700, gold:92040}},
  {id:'hz456b', kind:'investigate', n:'An Imperial Decree', icon:'📜', ch:456, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'From Hugh.',
   clues:['Soon after, royal guards from Hugh arrive at the Stanson estate with an imperial decree and special rewards for Levi\'s continued service to the realm.', '"By order of His Majesty and the Imperial Court, Levi Stanson is recognized as a Noble Archer and a trusted field operative. He is a permanent member of Lady Jade Gold\'s travelling party. His Majesty commends Levi\'s many contributions and grants these rewards in honor of his ongoing service."'], rw:{xp:449000, gold:92100}, needFlag:'inv_hz456a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz456c', kind:'investigate', n:'His Place Is on the Road', icon:'🏹', ch:456, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Still hunting the Fifteen Evils.',
   clues:['Jade: "Levi continues to travel with me and our companions. We are still hunting the remaining Fifteen Evils. There is much left to be done." Sally: "Levi\'s place has always been on the road, where he can use his strength and his heart for a greater good."', 'Levi: "I am still a son of House Stanson. But my duty also belongs to the court, to Lady Jade, our companions, and to the realm."'], rw:{xp:449300, gold:92160}, needFlag:'inv_hz456b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz456d', kind:'investigate', n:'Different Paths, the Same Family', icon:'🌙', ch:456, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'His parents accept it.',
   clues:['The father: "We were wrong to think you had abandoned your home. What you have done is not absence, but a different and greater form of service. You have brought honor to our family." The mother: "You are still our son, Levi. You do not need to stay at the estate to be part of House Stanson. Your path is difficult, but we are proud of you. Always."', 'Leon: "I will keep the estate strong in your absence. House Stanson will always be your home. No matter where your path takes you." Different paths, but the same family.'], rw:{xp:449600, gold:92220}, needFlag:'inv_hz456c', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz457a', kind:'investigate', n:'What If I\'m Pregnant?', icon:'🌙', ch:457, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Late at night in Levi\'s home.',
   clues:['Late at night, in Levi\'s home. It was supposed to be a peaceful evening together. Instead, Sally suddenly felt awful. Sally: "Ugh... I feel so nauseous... And I can\'t even remember when my last period was... What if... I\'m pregnant?"', 'Levi: "...! Don\'t think the worst yet, but we should be sure. I\'ll call Sky. He can examine you right away."'], rw:{xp:449900, gold:92280}},
  {id:'hz457b', kind:'investigate', n:'I\'ll Just Take Your Pulse', icon:'🩺', ch:457, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Sky is calm.',
   clues:['Sky: "You called for me? I hope it\'s nothing serious..." Sally: "P-Please don\'t look at me like that... I\'m just... feeling unwell. That\'s all!"', 'Sky: "Relax, Sally, I\'ll just take your pulse and check a few other signs. Try to breathe evenly."'], rw:{xp:450200, gold:92340}, needFlag:'inv_hz457a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz457c', kind:'investigate', n:'You\'re Not Pregnant', icon:'🌿', ch:457, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Fatigue and stress.',
   clues:['Sky: "Your pulse is steady, just a bit stressed. You\'re not pregnant. What you\'re experiencing is most likely due to fatigue, recent stress, and irregular sleep. Your body is simply out of balance. I\'ll prepare a gentle herbal tonic to help restore your energy."', 'Sally: "I\'m NOT pregnant?! Thank the heavens...!" Levi: "Phew... That\'s a relief... You really scared me."'], rw:{xp:450500, gold:92400}, needFlag:'inv_hz457b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz457d', kind:'investigate', n:'We Need to Be More Careful', icon:'💭', ch:457, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Not a game.',
   clues:['Sky: "Still, you should rest, eat properly, and try not to overwork yourself. If your cycle remains irregular, let me know. I\'ll leave the herbs with you. Good night."', 'After Sky left, Sally: "That scare made me realize something. We can\'t keep pretending this isn\'t a possibility forever, can we?" Levi: "...You\'re right. We need to be more careful from now on. I never want to see you that scared again."'], rw:{xp:450800, gold:92460}, needFlag:'inv_hz457c', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz458a', kind:'investigate', n:'Neither of Us Is Ready', icon:'💬', ch:458, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'After the scare.',
   clues:['After the scare, Sally and Levi finally talk about the possibility seriously. Sally: "Today really scared me... For a moment I thought... what if it was real? I\'m not ready for a child. We still have so many things to do. The remaining Fifteen Evils aren\'t defeated yet."', 'Levi: "No. I\'m not ready either. Our lives are too unpredictable right now. A child would deserve more stability than we can give."'], rw:{xp:451100, gold:92520}},
  {id:'hz458b', kind:'investigate', n:'We Haven\'t Figured Out What We Are', icon:'💭', ch:458, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Not officially together.',
   clues:['Sally: "And... we haven\'t even figured out what we are. We are not officially together. Sometimes I wonder if this is fair to you. You could choose someone who wants the life a noble son is expected to have."', 'Levi: "I chose this life. I chose to stay with you. Not because I have to, and not because of family expectations, but because I want to. Even if we never get married, even if we never have a child... being with you is still my choice."'], rw:{xp:451400, gold:92580}, needFlag:'inv_hz458a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz458c', kind:'investigate', n:'Our Decision', icon:'🕯️', ch:458, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Not a scare.',
   clues:['Sally: "So if one day... we do want a child, it should be because we both truly want it. Not because of a scare. Not because the family expects it. Not because we feel we should. If we ever decide on it, I want it to be our decision. Until then... let\'s just focus on what we have right now."', 'Levi: "Right now... I just want you. No fears, no pressure. Just you."'], rw:{xp:451700, gold:92640}, needFlag:'inv_hz458b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz458d', kind:'investigate', n:'Until Then', icon:'🌙', ch:458, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Maybe one day.',
   clues:['Levi: "Let\'s get some rest. Tomorrow we can deal with missions, meeting the next clue, and all the chaos again. For now... just sleep. You\'re safe. You\'re with me."', 'Sally: "...Maybe one day. When the world is less chaotic, when we\'re in a better place... We can think about it again. Together." Levi: "Until then... we do this instead." The scare does not push them toward marriage or separation. Any future together should be something they choose.'], rw:{xp:452000, gold:92700}, needFlag:'inv_hz458c', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz459a', kind:'investigate', n:'It Has Been Far Too Long', icon:'🍵', ch:459, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Jade and the Stansons.',
   clues:['Levi\'s father: "Jade. It has been far too long. You have grown even more remarkable than the last time we saw you." Jade: "Uncle, Aunt. It\'s wonderful to see you both again. Please don\'t be so formal with me. I\'m always glad to return to the Stanson estate."', 'Levi\'s mother: "How are your parents, Jade? Has your travelling been going smoothly? It must have been busy since Adrian\'s wedding."'], rw:{xp:452300, gold:92760}},
  {id:'hz459b', kind:'investigate', n:'A Permanent Companion', icon:'🏹', ch:459, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Noble Archer.',
   clues:['Jade: "The travels have been full, but very meaningful. Prince Devon, Princess Sera, and Princess Zhaoning, Sally, all play important roles. Levi is always with us as a permanent companion. He serves as a field operative and Noble Archer, supporting our party in many ways. His skills, judgment, and dedication have been invaluable."', 'His father: "The King spoke highly of your work. Levi, you have done a great deal for the realm."'], rw:{xp:452600, gold:92820}, needFlag:'inv_hz459a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz459c', kind:'investigate', n:'An Extension of Your Values', icon:'💭', ch:459, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Not a rejection.',
   clues:['Jade: "Levi has always cared deeply about people beyond the estate. He doesn\'t see his work as a rejection of his family. He sees it as an extension of the values you taught him: to protect others, fulfill his responsibilities, and do what is right."', 'His father: "We understand now. You are not an absent heir. You are Levi Stanson, Noble Archer. You represent the best of our family, and that is an honor in itself."'], rw:{xp:452900, gold:92880}, needFlag:'inv_hz459b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz459d', kind:'investigate', n:'Take Care of Each Other', icon:'🌙', ch:459, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'The bond endures.',
   clues:['His mother: "We are grateful to you, Jade. For walking this path with our son, and for the positive influence you\'ve had on him. Please take care of each other. Your work matters, not just to House Stanson, but to the entire realm."', 'Levi\'s parents no longer see his path as a rejection of his place, but as a different way of upholding it. The bond between the Stanson family and Jade endures.'], rw:{xp:453200, gold:92940}, needFlag:'inv_hz459c', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz460a', kind:'investigate', n:'To a Lifetime of Happiness', icon:'🏮', ch:460, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'The wedding toast.',
   clues:['Lenny\'s wedding brought everyone together, a rare and precious day of peace, filled with family, laughter, and celebration. Lenny: "To a lifetime of happiness together!"', 'A toast: "May your days be filled with love, joy, and a home always full of warmth."'], rw:{xp:453500, gold:93000}},
  {id:'hz460b', kind:'investigate', n:'So Many Red Envelopes', icon:'🧧', ch:460, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Wedding gifts.',
   clues:['A pile of red envelopes: "So many red envelopes! Lenny, you\'re already richer today!"', 'The party: "Congratulations, Lenny. Seeing you happy means so much to all of us."'], rw:{xp:453800, gold:93060}, needFlag:'inv_hz460a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz460c', kind:'investigate', n:'No Investigations, No Emergencies', icon:'🍶', ch:460, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'A rare day.',
   clues:['"It\'s been too long since we\'ve all had a day like this. No investigations, no emergencies... just family, food, wine, and celebration at last!"', '"This is the kind of day we should have more often." "A peaceful day with family... truly rare. Let\'s simply enjoy it."'], rw:{xp:454100, gold:93120}, needFlag:'inv_hz460b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz460d', kind:'investigate', n:'The Luckiest Man Alive', icon:'🌹', ch:460, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'The bride\'s veil.',
   clues:['Lenny to his veiled bride: "You look absolutely beautiful." Lenny: "I\'m the luckiest man alive."', 'For a brief, shining moment, there were no looming threats, no political storms, and no battles to fight. Just family, friends, and a new beginning, a rare and precious day of happiness at the Stanson estate.'], rw:{xp:454400, gold:93180}, needFlag:'inv_hz460c', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz461a', kind:'investigate', n:'A Beautiful Wedding', icon:'🏮', ch:461, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Everyone at ease.',
   clues:['Lenny\'s wedding is a joyous occasion for the Stanson family. The household finally has an heir, and the future is secure. For once, everyone can simply enjoy the celebration together before the road calls us onward. "It\'s a beautiful wedding." "Lenny looks very happy."', '"For once, no demons, no investigations, no emergencies. Just good wine and good company. This is rare."'], rw:{xp:454700, gold:93240}},
  {id:'hz461b', kind:'investigate', n:'Youthful Recklessness', icon:'🌸', ch:461, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'Levi\'s mother notices.',
   clues:['Levi\'s mother quietly notices the way Levi and Sally orbit one another, and chooses not to interfere, merely chuckling to herself at their youthful recklessness.', '"They really are fond of each other." "Let them be. Youthful recklessness is a beautiful thing."'], rw:{xp:455000, gold:93300}, needFlag:'inv_hz461a', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz461c', kind:'investigate', n:'How Many Weddings?', icon:'💸', ch:461, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'We are going to go broke.',
   clues:['"So... Roc and Delilah\'s wedding is next, right?" "Yes. There\'s another banquet, another set of gifts, and another long journey. We are going to go broke at this rate."', '"Adrian\'s wedding... Lenny\'s wedding... Now Roc and Delilah\'s wedding... How many weddings does this team actually have?! At this rate, our mission rewards will just go to wedding gifts and travel costs." "...As always."'], rw:{xp:455300, gold:93360}, needFlag:'inv_hz461b', lockMsg:'🔒 Finish the previous clue first'},
  {id:'hz461d', kind:'investigate', n:'The Road Calls Onward', icon:'🌅', ch:461, need:2, ambush:[], lo:96, roles:['jade', 'levi', 'sally'],
   desc:'The arc ends warmly.',
   clues:['As the celebration ends, the party prepares to leave. Lenny is now the household heir, the Stanson succession is secure, and Levi\'s parents fully accept that their eldest son will continue to travel with Jade.', 'The arc ends warmly. Lenny\'s marriage gives the Stanson family a stable future, Levi\'s bond with Sally is stronger than before, and the group looks ahead to the next journey, with another wedding (and more expenses) already on the horizon.'], rw:{xp:455600, gold:93420}, needFlag:'inv_hz461c', lockMsg:'🔒 Finish the previous clue first'},
);
